-- 1. Enable RLS on the table
ALTER TABLE documents ENABLE ROW LEVEL SECURITY;

-- 2. Define policy for all DML operations
CREATE POLICY tenant_isolation_policy ON documents
FOR ALL
USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::UUID);

-- 3. Application sets tenant ID at connection start
SET LOCAL app.current_tenant_id = '11111111-2222-3333-4444-555555555555';

-- Returns ONLY rows matching tenant 11111111-2222...
SELECT * FROM documents;

ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE accounts FORCE ROW LEVEL SECURITY;

CREATE POLICY accounts_tenant_isolation
ON accounts
USING (tenant_id = current_setting('app.tenant_id', true)::uuid)
WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- Per request, the application sets the tenant
SET LOCAL app.tenant_id = '3f2a9c10-0000-0000-0000-000000000001';

SELECT * FROM accounts;   -- only rows for that tenant are visible
